 async void Step(bool back){if(media==null||busy||previewMode)return;await player.Pause(true);await FlushSeek();double target=SourceTime(Math.Clamp(EditedTime(position)+(back?-1:1)/media.Fps,0,Spans().Sum(s=>s.End-s.Start)));if(Math.Abs(target-position)>2/media.Fps){Seek(target);await FlushSeek();}else await player.Step(back);}
 void Zoom(double multiplier){if(media==null)return;double duration=Spans().Sum(s=>s.End-s.Start);double length=timeline.ViewLength>0?timeline.ViewLength:duration;if(multiplier==0){timeline.ViewStart=timeline.ViewLength=0;}else{length=Math.Clamp(length*multiplier,Math.Min(2,duration),duration);timeline.ViewLength=length;timeline.ViewStart=Math.Clamp(EditedTime(position)-length/2,0,Math.Max(0,duration-length));}Redraw();}
 async Task PreviewJoin(){if(Current is not Cut c||media==null)return;string output=Path.Combine(Engine.Home,"join-"+Guid.NewGuid().ToString("N")+".mp4");await Work(async ct=>{Status("カット後のつながりを準備中…");var keep=new List<(double,double)>();if(c.Start>0)keep.Add((Math.Max(0,c.Start-3),c.Start));if(c.End<media.Duration)keep.Add((c.End,Math.Min(media.Duration,c.End+3)));if(keep.Count==0)throw new IOException("残る映像がありません。");await Engine.Export(file,output,media,keep,"libsvtav1",2,ct,Progress);player.Close();CleanupPreview();previewFile=output;previewMode=true;await player.Open(video.Handle,output,ct);await player.Pause(false);Status("カット後の前後3秒をアプリ内で再生 ／ 元動画へで戻る");});}
 async Task ReturnToSource(){if(!previewMode||media==null)return;await Work(async ct=>{player.Close();CleanupPreview();previewMode=false;await player.Open(video.Handle,file,ct);await player.Seek(position);UpdatePosition();});}
 void CleanupPreview(){if(previewFile==null)return;try{File.Delete(previewFile);}catch(IOException){}previewFile=null;}
 void Progress(double p)=>Ui(()=>progress.Value=(int)Math.Clamp(p*1000,0,1000));
 void SaveProject(){if(media==null)return;using var d=new SaveFileDialog{Filter="編集内容|*.inferno.json",FileName=Path.GetFileNameWithoutExtension(file)+".inferno.json"};if(d.ShowDialog(this)!=DialogResult.OK)return;var f=new FileInfo(file);string tmp=d.FileName+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(tmp,JsonSerializer.Serialize(new Project(file,f.Length,f.LastWriteTimeUtc,cuts),new JsonSerializerOptions{WriteIndented=true}));File.Move(tmp,d.FileName,true);dirty=false;Status("編集内容を保存しました。");}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 void LoadProject(){if(media==null||!DiscardChanges())return;using var d=new OpenFileDialog{Filter="編集内容|*.inferno.json;*.cmcut.json"};if(d.ShowDialog(this)!=DialogResult.OK)return;try{var project=JsonSerializer.Deserialize<Project>(File.ReadAllText(d.FileName))??throw new IOException("編集内容を読めません。");var f=new FileInfo(file);if(!project.File.Equals(file,StringComparison.OrdinalIgnoreCase)||project.Bytes!=f.Length||project.Modified!=f.LastWriteTimeUtc)throw new IOException("選択中の動画と一致しません。");foreach(var c in project.Cuts)if(!double.IsFinite(c.Start)||!double.IsFinite(c.End)||c.Start<0||c.End<=c.Start||c.End>media.Duration)throw new IOException("不正な範囲があります。");_=Engine.Keep(project.Cuts,media.Duration);Remember();cuts=project.Cuts;RenderRanges();dirty=false;Status("編集内容を開きました。");}catch(Exception e){MessageBox.Show(this,e.Message);}}
 async Task Export(){if(media==null||!cuts.Any(c=>c.Selected)){Status("I → Oで削除区間を追加してください。");return;}using var d=new SaveFileDialog{Filter="MP4 AV1|*.mp4",FileName=Path.GetFileNameWithoutExtension(file)+"_cut_AV1.mp4",InitialDirectory=Path.GetDirectoryName(file)};if(d.ShowDialog(this)!=DialogResult.OK)return;if(File.Exists(d.FileName)){Status("上書きしません。別名を指定してください。");return;}if(MessageBox.Show(this,$"{cuts.Count(c=>c.Selected)}区間を除いた別ファイルを作ります。\n元動画は残します。字幕・データ放送・副音声は出力対象外です。","カットして書き出し",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;string codec=new[]{"av1_nvenc","av1_qsv","av1_amf","libsvtav1"}[encoder.SelectedIndex];int rate=(int)bitrate.Value;await Work(async ct=>{progress.Value=0;Status("MP4／AV1出力中…");var keep=Engine.Keep(cuts,media.Duration);renderJob=new RenderJob(file,d.FileName,$"MP4 / AV1　{encoder.Text}　{rate} Mbps　{media.Width} × {media.Height}　音声 AAC",keep.Sum(s=>s.End-s.Start));renderPanel.Attach(renderJob);renderPanel.Visible=true;renderRow!.Height=230;await Engine.Export(file,d.FileName,media,keep,codec,rate,ct,Progress,renderJob);progress.Value=1000;Status("出力完了："+d.FileName);});}
 bool EditingText(){Control? c=ActiveControl;while(c is ContainerControl container&&container.ActiveControl!=null)c=container.ActiveControl;return c is TextBoxBase||ranges.IsCurrentCellInEditMode;}
 protected override bool ProcessCmdKey(ref Message message,Keys key){if(!busy){if(key==Keys.Space){Toggle();return true;}if(!EditingText()){if(key==Keys.Delete){DeleteMarked();return true;}if(key==Keys.I){SetIn();return true;}if(key==Keys.O){AddOut();return true;}if(key==(Keys.Control|Keys.Z)){Undo();return true;}if(key==(Keys.Control|Keys.Y)){Redo();return true;}if(key is Keys.Left or Keys.Right){Step(key==Keys.Left);return true;}if(key is (Keys.Shift|Keys.Left) or (Keys.Shift|Keys.Right)){Seek(position+((key&Keys.KeyCode)==Keys.Left?-10:10)/(media?.Fps??29.97));return true;}}}return base.ProcessCmdKey(ref message,key);}
 internal void Capture(string path){using var image=new Bitmap(Width,Height);DrawToBitmap(image,new Rectangle(Point.Empty,Size));image.Save(path);}
 internal void TestContent(string path,Media info,List<Cut> items){cuts=Copy(items);dirty=false;RenderRanges();Seek(items.FirstOrDefault()?.Start??0);}
 internal record Project(string File,long Bytes,DateTime Modified,List<Cut> Cuts);
 internal EmbeddedPlayer TestPlayer=>player;internal Timeline TestTimeline=>timeline;internal double TestPosition=>position;internal int TestCutCount=>cuts.Count;
 internal void TestShuttle(double? distance){desiredShuttle=distance.HasValue?ShuttleSpeed.FromDistance(distance.Value):0;_=ApplyShuttle();}internal long InputGestureCount=>rightInput?.GestureCount??0;
 internal void TestShowRender(RenderJob job){renderJob=job;renderPanel.Attach(job);renderPanel.Visible=true;renderRow!.Height=230;}
 internal void TestMarkIn()=>SetIn();internal void TestMarkOut()=>AddOut();internal void TestDelete()=>DeleteMarked();internal double TestSourceTime(double edited)=>SourceTime(edited);internal void TestUndo()=>Undo();internal void TestRedo()=>Redo();internal void TestSeek(double time)=>Seek(time);internal void TestSpace(){var m=new Message();ProcessCmdKey(ref m,Keys.Space);}internal void TestClearDirty()=>dirty=false;
}
